static bool bootOTACheckDone = false;

U8G2_SH1106_128X64_NONAME_F_HW_I2C u8g2(U8G2_R0, U8X8_PIN_NONE, OLED_SCL, OLED_SDA);
// U8G2_SH1106_128X64_NONAME_F_HW_I2C u8g2(
//     U8G2_R0,
//     U8X8_PIN_NONE,
//     OLED_SCL,
//     OLED_SDA);
inline void drawWiFiStatusUI()
{
    Global::WiFiState state = Global::getWiFiState();

    u8g2.clearBuffer();
    u8g2.setFont(u8g2_font_6x12_tf);

    switch (state)
    {
    case Global::WIFI_NO_CREDENTIALS:
    case Global::WIFI_SETUP_PORTAL:
        u8g2.drawStr(0, 12, "4ngryROBO Setup");
        u8g2.drawHLine(0, 17, 128);
        u8g2.drawStr(0, 31, "Connect to WiFi:");
        u8g2.drawStr(0, 43, "4ngryROBO");
        u8g2.drawStr(0, 55, "Pass: 12345678");
        // u8g2.drawStr(0, 64, "Open 192.168.4.1");
        u8g2.drawStr(0, 61, "Open 192.168.4.1");
        break;

    case Global::WIFI_CONNECTING:
        u8g2.drawStr(0, 12, "4ngryROBO");
        u8g2.drawHLine(0, 17, 128);
        u8g2.drawStr(0, 34, "Connecting to WiFi");
        u8g2.drawStr(0, 49, "Please wait...");
        break;

    case Global::WIFI_UNAVAILABLE:
        u8g2.drawStr(0, 12, "4ngryROBO");
        u8g2.drawHLine(0, 17, 128);
        u8g2.drawStr(0, 34, "WiFi unavailable");
        u8g2.drawStr(0, 48, "Retrying in background");
        break;

    case Global::WIFI_CONNECTED:
        u8g2.drawStr(0, 12, "WiFi Connected");
        u8g2.drawHLine(0, 17, 128);
        u8g2.drawStr(0, 34, "Network ready");
        break;
    }

    u8g2.sendBuffer();
}
void setup()
{
    Serial.begin(115200);
    delay(1500);

    Serial.println();
    Serial.println("========== 4ngryROBO BOOT ==========");
    String runtimeChipModel = ESP.getChipModel();
    Serial.printf("[DIAG] Runtime chip model: %s | revision: %u | cores: %u | flash: %u bytes\n",
                  runtimeChipModel.c_str(), (unsigned)ESP.getChipRevision(), (unsigned)ESP.getChipCores(), (unsigned)ESP.getFlashChipSize());
    Serial.println("[DIAG] If this model differs from the PlatformIO board target, stop OTA and correct platformio.ini.");
    Serial.println("[BOOT] setup() entered");

    Serial.println("[BOOT] Initializing display driver...");
    BootUI::initDriver();
    Serial.println("[BOOT] Display driver initialized");

    Serial.println("[BOOT] Initializing display...");
    BootUI::initDisplay();
    ExtraScreens::loadDeviceSettings();
    u8g2.setContrast(ExtraScreens::getBrightness());
    ExtraScreens::playBuzzerDemo(0); // Short configurable startup chime.
    Serial.println("[BOOT] Display initialized");

    randomSeed(analogRead(0) ^ (analogRead(1) << 8));
    lastScreenActivityMs = millis();

    initExpression(IDLE, anim);
    exprStartMs = millis();
    scheduleIdleBlink(millis());
    scheduleIdleLook(millis());

    Serial.print("[BOOT] Firmware version: ");
    Serial.println(FIRMWARE_VERSION);

    Serial.println("[BOOT] Playing boot animation...");
    BootUI::playBootAnimation();
    Serial.println("[BOOT] Boot animation finished");

    Serial.println("[BOOT] Starting WiFi...");
    Global::WiFiOn();
    Serial.println("[BOOT] Global::WiFiOn() returned");

    Serial.println("========== BOOT COMPLETE ==========");

    BootUI::initTime();
    BootUI::initWeather();

    // Exactly one automatic OTA check during boot. Never restart Wi-Fi here.
    if (WiFi.status() == WL_CONNECTED)
    {
        Serial.println("[OTA] Performing one boot-time firmware check...");
        bootOTACheckDone = true;
        checkfirmwareUpdate();
    }
    else
    {
        Serial.println("[OTA] Waiting for Wi-Fi before the one-time boot update check.");
    }
}

void loop()
{
    Global::updateWiFi();

    unsigned long now = millis();

    // Always process touch, including when Wi-Fi is disconnected.
    handleTouch(now);

    // Process AP start/stop requests from the touch handler.
    Global::updateWiFi();
    DrawingCanvas::servicePendingTasks();
    ExtraScreens::updateTimer();

    if (!bootOTACheckDone && WiFi.status() == WL_CONNECTED)
    {
        bootOTACheckDone = true;
        Serial.println("[OTA] Running deferred one-time boot update check.");
        checkfirmwareUpdate();
        now = millis();
    }

    Global::WiFiState state = Global::getWiFiState();

    // Show a non-blocking hold-progress screen after a deliberate long press
    // begins; releasing early still follows the original navigation behavior.
    if (touchActive && !webFeatureScreenActive && now - touchStartMs >= 2000UL)
    {
        static uint32_t lastHoldRender = 0;
        if (now - lastHoldRender >= 35)
        {
            lastHoldRender = now;
            int progress = (int)constrain((now - touchStartMs) * 100UL / 5000UL, 0UL, 100UL);
            u8g2.clearBuffer();
            u8g2.setFont(u8g2_font_6x10_tf);
            u8g2.drawStr(8, 17, "HOLD FOR AP MODE");
            u8g2.drawStr(8, 31, "5s Hold for AP Mode enable");
            u8g2.drawFrame(8, 40, 112, 10);
            int fill = (108 * progress) / 100;
            if (fill > 0)
                u8g2.drawBox(10, 42, fill, 6);
            char percent[8];
            snprintf(percent, sizeof(percent), "%d%%", progress);
            u8g2.drawStr(54, 61, percent);
            u8g2.sendBuffer();
        }
        return;
    }

    // Clock-screen timer and weather-screen 3-day forecast are independent overlays.
    if (ExtraScreens::timerActive())
    {
        static uint32_t lastTimerRender = 0;
        if (now - lastTimerRender >= 100)
        {
            lastTimerRender = now;
            ExtraScreens::renderTimer(u8g2);
        }
        return;
    }
    if (ExtraScreens::forecastActive())
    {
        static uint32_t lastForecastRender = 0;
        if (now - lastForecastRender >= 500)
        {
            lastForecastRender = now;
            ExtraScreens::renderForecast(u8g2);
        }
        return;
    }

    // Screen 4 is independent from the normal three-screen navigation.
    // WebServer continues to be serviced by Global::updateWiFi().
    if (webFeatureScreenActive)
    {
        static uint32_t lastWebRender = 0;
        if (DrawingCanvas::needsRender() && now - lastWebRender >= 25)
        {
            DrawingCanvas::renderToOLED(u8g2);
            lastWebRender = now;
        }
        return;
    }

    // A boot-time AP (no saved credentials) keeps showing setup instructions.
    // After a 5-second hold opened the web-feature session, a tap can return
    // to the normal expression / clock / weather screens while AP stays online.
    if (state == Global::WIFI_SETUP_PORTAL && !webPortalSessionActive && !webSessionDismissed)
    {
        drawWiFiStatusUI();
        return;
    }

    // Show Wi-Fi status while connecting or unavailable, but do not block
    // the normal screens during a manually requested AP session.
    if (state != Global::WIFI_CONNECTED &&
        !(state == Global::WIFI_SETUP_PORTAL && webPortalSessionActive) &&
        !webSessionDismissed)
    {
        drawWiFiStatusUI();
        return;
    }

    // Update local time once per second.
    static uint32_t lastTimeUpdate = 0;

    if (now - lastTimeUpdate >= 1000)
    {
        lastTimeUpdate = now;
        updateLocalTime();
    }

    // Frame-rate gate.
    if (now - lastFrameMs < FRAME_MS)
        return;

    lastFrameMs = now;

    float ms = (float)now;

    // Expression transition.
    if (transitioning)
    {
        transitionT += 0.08f;

        if (transitionT >= 1.0f)
        {
            transitioning = false;

            currentExpr = nextExpr;
            exprStartMs = now;

            initExpression(currentExpr, anim);

            if (currentExpr == IDLE)
            {
                scheduleIdleBlink(now);
                scheduleIdleLook(now);
            }
        }
        else
        {
            float squeeze;

            if (transitionT < 0.5f)
                squeeze = 1.0f - easeIn(transitionT * 2.0f);
            else
                squeeze = easeOut((transitionT - 0.5f) * 2.0f);

            anim.eyeScaleX = squeeze;
            anim.eyeScaleY = squeeze;
            anim.bounce = (1.0f - squeeze) * -3.0f;
        }
    }
    else
    {
        if (currentExpr == IDLE)
        {
            if (now >= idleNextBlink)
            {
                float blinkPhase =
                    fmodf((now - idleNextBlink) / 200.0f, 1.0f);

                float c;

                if (blinkPhase < 0.5f)
                    c = easeIn(blinkPhase * 2.0f);
                else
                    c = easeOut((1.0f - blinkPhase) * 2.0f);

                anim.eyeScaleY = 1.0f - 0.9f * c;

                if (blinkPhase > 0.95f)
                {
                    anim.eyeScaleY = 1.0f;
                    scheduleIdleBlink(now);
                }
            }

            if (now >= idleNextLook)
            {
                idleGazeTarget =
                    (float)random(-3, 4) / 3.0f;

                scheduleIdleLook(now);
            }

            idleGazeX +=
                (idleGazeTarget - idleGazeX) * 0.06f;
        }

        updateExpression(currentExpr, anim, ms);
    }

    // Normal OLED rendering.
    u8g2.clearBuffer();
    u8g2.setDrawColor(1);
    renderScreen(currentScreen);
    u8g2.sendBuffer();
}

